-- ---------------------------------------------------------------- logic bridge
-- Finds the original UI still running in the game and forwards every click,
-- hover and text change from this clone straight into its real callbacks, so
-- the copied interface does exactly what the original one does.
local ORIGINAL_NAME = "a27b741e-9e37-462a-b765-603cefde25c7"
local function findOriginal()
    local roots = {}
    local okh, hidden = pcall(function() return gethui and gethui() end)
    if okh and hidden then roots[#roots+1] = hidden end
    roots[#roots+1] = game:GetService("CoreGui")
    local lp = game:GetService("Players").LocalPlayer
    if lp then
        local pg = lp:FindFirstChildOfClass("PlayerGui")
        if pg then roots[#roots+1] = pg end
    end
    for _, r in ipairs(roots) do
        local ok, kids = pcall(function() return r:GetDescendants() end)
        if ok then
            for _, d in ipairs(kids) do
                if d:IsA("ScreenGui") and d.Name == ORIGINAL_NAME then return d end
            end
        end
    end
end

local original = findOriginal()
local fire = getconnections or get_signal_cons
if original and fire then
    local function resolve(path)
        local node = original
        for part in string.gmatch(path, "[^,]+") do
            local idx = tonumber(part)
            if not idx then return nil end
            local kids = node:GetChildren()
            node = kids[idx]
            if not node then return nil end
        end
        return node
    end
    local function link(clone, path)
        local src = resolve(path)
        if not src then return end
        local function relay(signalName)
            local okc, cl = pcall(function() return clone[signalName] end)
            local oks, sg = pcall(function() return src[signalName] end)
            if not (okc and oks and cl and sg) then return end
            cl:Connect(function(...)
                local okf, cons = pcall(fire, sg)
                if not okf then return end
                for _, c in ipairs(cons) do
                    if c.Function then pcall(c.Function, ...) end
                end
            end)
        end
        if clone:IsA("GuiButton") then
            relay("MouseButton1Click"); relay("MouseButton1Down"); relay("MouseButton1Up")
            relay("MouseButton2Click"); relay("MouseEnter"); relay("MouseLeave"); relay("Activated")
        end
        if clone:IsA("TextBox") then
            clone.FocusLost:Connect(function(enter)
                pcall(function() src.Text = clone.Text end)
                local okf, cons = pcall(fire, src.FocusLost)
                if okf then for _, c in ipairs(cons) do if c.Function then pcall(c.Function, enter) end end end
            end)
        end
        -- mirror the original's visual state back onto the clone
        src.Changed:Connect(function(prop)
            pcall(function() clone[prop] = src[prop] end)
        end)
    end
    for _, entry in ipairs(CLONE_LINKS) do link(entry[1], entry[2]) end
else
    warn("[Calcium] original UI not found or executor lacks getconnections — clone is visual only")
end
